#!/usr/bin/env node
// lamba test: run your Lamba app the way Lamba TV runs it, headless, and say in plain words what happened.
//   node lamba-test.mjs [my-app] [--quick] [--headed] [--shots <folder>]
//   node lamba-test.mjs my-app --serve [--port 8787] [--host 0.0.0.0]    play it yourself, no test (see the end of this list)
// It needs Playwright once, in this folder:
//   npm i -D playwright && npx playwright install chromium
// What it does, for each app folder (one with lamba.json; with none named: the one here, or every folder next to it):
//   1. the check Lamba's server runs on an upload (the same code as lamba-check.mjs), with what to fix
//   2. the app in the real simulator (Lamba's own screen host, the Host's phone with the real settings drawer, a Player's
//      phone, the sealed frame and its content rules, the room's limits), served from this computer: no network, no account
//   3. the screen at 1920 x 1080 and at the old screen size (960 x 540), the Host's phone and one Player's phone (if Players join)
//   4. a tap on each of the Host's action tiles (lamba.json actions), the Player's remote at 390 x 844 (it fills the phone and
//      never scrolls), a tap on the Player's main key, then every settings group in lamba.json, choice by choice, sent to the screen
//   5. errors in any page, problems the room or the sealed frame refused, every SDK message both ways (the simulator's log)
//   6. at the end, a short summary in three columns: what was tested (the screen, the Host's phone, the Player's remote),
//      the result, and what to fix (in the terminal, in summary.md, and in summary.json as "table")
// With --serve it starts the same local server and prints one address: open it in any browser on this computer to see the
// screen, the Host's phone and a Player's phone side by side with your app already loaded (no Playwright needed). Reload
// the page to pick up edits. It runs until Ctrl+C. It listens on 127.0.0.1 only; --host 0.0.0.0 lets a phone on the same
// Wi-Fi open it too.
// It writes screenshots and summary.md (and summary.json) to ./lamba-test-shots/ next to this script, prints the
// summary, and ends with exit code 0 when nothing needs fixing, 1 when something does, 2 when it could not run.
//
// Why the simulator is inside this file: so the test runs offline, from your folder, with the exact simulator and SDK
// that this kit was made with (tools/sdk_kit.mjs puts them in SIM below). Inside Lamba's own repository, SIM is empty and
// the files are read from the repository itself.
import { createServer } from "node:http";
import { readFileSync, readdirSync, statSync, existsSync, mkdirSync, writeFileSync, rmSync } from "node:fs";
import { join, resolve, relative, basename, dirname, sep, extname } from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";
import { inflateRawSync } from "node:zlib";
import os from "node:os";

const HERE = dirname(fileURLToPath(import.meta.url));
const SIM = "";   // the kit's build puts the simulator and the SDK here: base64 of a deflated JSON { path: base64 }
const args = process.argv.slice(2), flag = f => args.includes(f);
const opt = k => { const i = args.indexOf(k); return i > -1 ? args[i + 1] : null; };
const QUICK = flag("--quick"), HEADED = flag("--headed"), SERVE = flag("--serve");
const SHOTS = resolve(opt("--shots") || join(HERE, "lamba-test-shots"));
const named = args.filter((a, i) => !a.startsWith("-") && !["--shots", "--port", "--host"].includes(args[i - 1]));
const wait = ms => new Promise(r => setTimeout(r, ms));
const say = (...a) => console.log(...a);

// ---------- Playwright ----------
let chromium;
if (!SERVE) try { ({ chromium } = createRequire(join(HERE, "lamba-test.mjs"))("playwright")); }
catch (e) {
  say("lamba test: Playwright is not installed here. Run these two commands in this folder, then run the test again:\n  npm i -D playwright\n  npx playwright install chromium");
  process.exit(2);
}

// ---------- the simulator's files: from this script, or from Lamba's repository ----------
const REPO = SIM ? null : [join(HERE, ".."), HERE].find(d => existsSync(join(d, "shell/sdk/lamba.js")) && existsSync(join(d, "devs/simulator/sim.js")));
if (!SIM && !REPO) { say("lamba test: this copy has no simulator inside it. Get the newest at https://lamba.tv/devs/kit/lamba-test.mjs"); process.exit(2); }
const FILES = SIM ? (() => { const o = JSON.parse(inflateRawSync(Buffer.from(SIM, "base64")).toString("utf8")); for (const k in o) o[k] = Buffer.from(o[k], "base64"); return o; })() : null;
const TYPES = { ".html": "text/html; charset=utf-8", ".js": "text/javascript", ".mjs": "text/javascript", ".css": "text/css", ".json": "application/json", ".svg": "image/svg+xml",
  ".png": "image/png", ".webp": "image/webp", ".jpg": "image/jpeg", ".woff2": "font/woff2", ".ttf": "font/ttf", ".zip": "application/zip", ".mp4": "video/mp4" };
const asked = new Set(), missing = new Set();
function file(p) {   // p: "devs/simulator/sim.js"
  if (FILES) return FILES[p] || null;
  const f = join(REPO, p);
  if (!f.startsWith(REPO + sep) || !existsSync(f) || !statSync(f).isFile()) return null;
  return readFileSync(f);
}
function serve(port, host, mine) {   // mine: { dir, slug } with --serve: the app's folder, read from disk on every request
  const server = createServer((q, r) => {
    let p = decodeURIComponent(new URL(q.url, "http://x").pathname).replace(/^\/+/, "");
    if (mine && p === "devs/kit/examples/" + mine.slug + ".zip") {
      try { const z = zipOf(mine.dir, mine.slug + "/"); r.writeHead(200, { "content-type": "application/zip", "cache-control": "no-store" }); r.end(z); }
      catch (e) { r.writeHead(500, { "content-type": "text/plain" }); r.end("could not read the app folder"); }
      return;
    }
    if (p === "" || p.endsWith("/")) p += "index.html";
    if (/(^|\/)\.\.?(\/|$)/.test(p)) { r.writeHead(404); r.end(); return; }
    let b = file(p);
    if (!b && !extname(p)) { p += "/index.html"; b = file(p); }
    asked.add(p);
    if (!b) { if (!/favicon|devs\/kit\/version\.json/.test(p)) missing.add(p); r.writeHead(404, { "content-type": "text/plain" }); r.end("not found"); return; }
    r.writeHead(200, { "content-type": TYPES[extname(p)] || "application/octet-stream", "cache-control": "no-store" }); r.end(b);
  });
  return new Promise((res, rej) => {
    const go = n => { server.once("error", e => { if (e.code === "EADDRINUSE" && n) go(0); else rej(e); }); server.listen(n, host || "127.0.0.1", () => { server.removeAllListeners("error"); res(server); }); };
    go(port || 0);
  });
}

// ---------- the app's folder, as a zip (what you would upload) ----------
const SKIP = n => n === "node_modules" || n.startsWith(".") || n === "lamba-test-shots";
function walk(dir) { const out = []; const go = d => { for (const n of readdirSync(d)) { const f = join(d, n); if (SKIP(n)) continue; if (statSync(f).isDirectory()) go(f); else out.push(relative(dir, f).split(sep).join("/")); } }; go(dir); return out.sort(); }
const CRC = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; CRC[n] = c >>> 0; }
const crc = b => { let c = 0xffffffff; for (let i = 0; i < b.length; i++) c = CRC[(c ^ b[i]) & 255] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
function zipOf(dir, prefix) {
  const parts = [], central = []; let at = 0; const paths = walk(dir);
  for (const rel of paths) {
    const data = readFileSync(join(dir, rel)), name = Buffer.from(prefix + rel, "utf8"), c = crc(data);
    const h = Buffer.alloc(30); h.writeUInt32LE(0x04034b50, 0); h.writeUInt16LE(20, 4); h.writeUInt16LE(0x800, 6); h.writeUInt32LE(c, 14); h.writeUInt32LE(data.length, 18); h.writeUInt32LE(data.length, 22); h.writeUInt16LE(name.length, 26);
    const e = Buffer.alloc(46); e.writeUInt32LE(0x02014b50, 0); e.writeUInt16LE(20, 4); e.writeUInt16LE(20, 6); e.writeUInt16LE(0x800, 8); e.writeUInt32LE(c, 16); e.writeUInt32LE(data.length, 20); e.writeUInt32LE(data.length, 24); e.writeUInt16LE(name.length, 28); e.writeUInt32LE(at, 42);
    parts.push(h, name, data); central.push(e, name); at += 30 + name.length + data.length;
  }
  const cd = Buffer.concat(central), end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0); end.writeUInt16LE(paths.length, 8); end.writeUInt16LE(paths.length, 10); end.writeUInt32LE(cd.length, 12); end.writeUInt32LE(at, 16);
  return Buffer.concat(parts.concat([cd, end]));
}

// ---------- driving the simulator ----------
const rigFrame = (p, rig) => p.frames().find(f => { try { return new URL(f.url()).searchParams.get("rig") === rig && /\/devs\/simulator\/(tv|phone)\.html/.test(f.url()); } catch (e) { return false; } });
async function sealed(p, rig, view, ms) {   // the app's own page inside a rig, in that view
  const end = Date.now() + (ms || 10000);
  while (Date.now() < end) {
    const r = rigFrame(p, rig);
    if (r) for (const f of p.frames()) if (f.parentFrame() === r && f.url() === "about:srcdoc") { const v = await f.evaluate(() => window.Lamba && Lamba.screen && Lamba.screen.view).catch(() => null); if (v === view) return f; }
    await wait(150);
  }
  return null;
}
const until = async (fn, ms) => { const end = Date.now() + (ms || 8000); let v; while (Date.now() < end) { v = await fn().catch(() => null); if (v) return v; await wait(150); } return v; };
const logLines = p => p.evaluate(() => [...document.querySelectorAll("#lines li")].map(l => ({ kind: (l.className.match(/k-(\w+)/) || [])[1] || "", who: (l.querySelector("b") || {}).textContent || "", text: (l.querySelector("span") || {}).textContent || "" }))).catch(() => []);
const slug = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 40) || "x";

async function testApp(dir, base, browser, n) {
  const m = JSON.parse(readFileSync(join(dir, "lamba.json"), "utf8")), id = basename(dir), out = join(SHOTS, n > 1 ? id : "");
  mkdirSync(out, { recursive: true });
  const R = { app: id, name: m.name || id, check: null, errors: [], problems: [], refused: [], messages: [], settings: [], shots: [], steps: [], notes: [] };
  let area = "Screen";   // what the steps below belong to: the summary table groups by it
  const step = (ok, text) => { R.steps.push({ ok, text, area }); say("  " + (ok === true ? "ok  " : ok === false ? "FIX " : "note") + " " + text); };
  const ctx = await browser.newContext({ viewport: { width: 1680, height: 1050 }, deviceScaleFactor: 1 });
  const p = await ctx.newPage();
  p.on("pageerror", e => R.errors.push("a page threw: " + e.message));
  p.on("console", c => { if (c.type() === "error" && !/favicon|fonts\.g|net::ERR|Failed to load resource|Content Security Policy/.test(c.text())) R.errors.push("console error: " + c.text().slice(0, 300)); });
  const shot = async (name, what, el) => { const f = join(out, name + ".png"); try { if (el) await el.screenshot({ path: f }); else await p.screenshot({ path: f }); R.shots.push({ file: relative(SHOTS, f), what }); } catch (e) { R.notes.push("no screenshot of " + what + ": " + e.message.split("\n")[0]); } };
  const tvShot = async (name, what) => { const box = await p.$("#tvScreen"); await shot(name, what, box); };
  // the simulator's log, kept as the test moves from page to page
  let seen = 0;
  const harvest = async () => {
    const L = await logLines(p);
    for (const l of L.slice(seen)) {
      if (l.kind === "problem") (/refused/.test(l.text) ? R.refused : R.problems).push(l.who + ": " + l.text);
      else if (l.kind === "word" || l.kind === "settings") R.messages.push(l.who + ": " + l.text);
    }
    seen = L.length;
  };
  const showRig = async rig => { await p.evaluate(r => { const i = [...document.querySelectorAll(".sim-phone")].findIndex(x => x.dataset.rig === r), t = document.querySelectorAll("#who button")[i]; if (t) t.click(); }, rig); await wait(250); };   // one phone shows at a time: the Remote control's Host | Player switch picks it
  const phoneShot = async (rig, name, what) => { await showRig(rig); const el = await p.$('figure.sim-phone[data-rig="' + rig + '"] .sim-glass'); if (el) await shot(name, what, el); };

  // 1. open the app as a zip, the way you upload it
  const pl = m.players || {}, guestsN = m.guests ? Math.max(1, Math.min(2, pl.min || 1, pl.max || 1)) : 0;   // two for a game that needs two
  await p.goto(base + "/devs/simulator/?join=skip" + (guestsN ? "&guests=" + guestsN : ""));   // (Players skip Lamba's join here: the remote is what is tested)
  await p.waitForSelector("#zipBtn", { timeout: 15000 });
  await p.setInputFiles("#zipInput", { name: id + ".zip", mimeType: "application/zip", buffer: zipOf(dir, id + "/") });
  const tv = await sealed(p, "tv", "screen", 15000);
  step(!!tv, tv ? "the screen page runs in Lamba's screen host (view screen)" : "the screen page never said hello: does it load ../../shell/sdk/lamba.js and call Lamba.ready?");
  const drawn = tv && await until(async () => (await logLines(p)).some(l => l.who === "Screen" && /^app: drawn/.test(l.text)), 6000);
  if (tv) step(!!drawn, drawn ? "it called Lamba.drawn() and the host faded it in" : "the host never faded the screen page in: call Lamba.drawn() once the page has drawn itself");
  await wait(1200);

  // 2. the check
  area = "Check";
  const badge = await until(() => p.evaluate(() => { const b = document.getElementById("checkBadge").textContent; return b && b !== "Checking" ? b : null; }), 20000);
  const items = await p.evaluate(() => [...document.querySelectorAll("#checkBody li")].map(l => l.textContent));
  const ready = badge === "Ready to upload";
  R.check = { ready, badge, problems: ready ? [] : items, notes: ready ? items : [] };
  step(ready, ready ? "the check passes (the same check Lamba's server runs)" : "the check found " + items.length + " to fix (below)" + (items.some(t => /phone design:/.test(t)) ? ", " + items.filter(t => /phone design:/.test(t)).length + " of them about the phone page building its own controls: " + items.filter(t => /phone design:/.test(t)).map(t => t.replace(/^.*?phone design: /, "")).join(" ").slice(0, 300) : ""));
  // the phone page must use Lamba's controls (docs/sdk/UI.md): the check's "phone design:" lines are flagged in the summary table
  const design = items.filter(t => /phone design:/.test(t));
  if (ready && design.length) step(null, "the phone page builds its own controls (" + design.length + "): " + design.map(t => t.replace(/^.*?phone design: /, "")).join(" ").slice(0, 400));
  if (ready && items.some(t => /placeholder clips/.test(t))) R.notes.push("Before you upload: replace the starter's placeholder clips with real clips of your app (clips/<name>.mp4 540 x 920, 6 to 14 s, and clips/<name>-poster.webp).");

  // 3. the screens
  area = "Screen";
  await tvShot("1-tv-1920x1080", "the screen, 1920 x 1080 (shown scaled)");
  await phoneShot("owner", "3-owner-phone", "the Host's phone: the live screen and one row of tiles");
  const owner = null;   // the Host's phone runs no page of the app's own (there is no controller view): its copy of the screen and its tiles
  area = "Host's phone";
  const copy = await sealed(p, "owner", "preview", 8000);
  step(!!copy, copy ? "the Host's phone shows a live copy of the screen (view preview)" : "the Host's phone shows no copy of the screen: does the screen page load and call Lamba.ready?");
  const tiles = await (rigFrame(p, "owner") || { evaluate: async () => 0 }).evaluate(() => document.querySelectorAll(".g-tile").length).catch(() => 0);
  step(tiles > 0, tiles > 0 ? "the Host's phone has its row of tiles (" + tiles + ")" : "the Host's phone drew no tiles");
  // the Host's action tiles (lamba.json actions): each reaches the screen as { type: "action", key }
  // the sheet starts closed (a handle row); open it first, as a finger would
  await (rigFrame(p, "owner") || { evaluate: async () => 0 }).evaluate(() => { const g = document.querySelector(".g-grab"); if (g && document.body.classList.contains("g-collapsed")) g.click(); }).catch(() => {}); await wait(900);
  for (const a of Array.isArray(m.actions) ? m.actions : []) {
    const before = (await logLines(p)).length, of = rigFrame(p, "owner");
    const tapped = of && await of.evaluate(k => { const b = document.querySelectorAll(".g-tile.sdk-act")[k]; if (!b) return false; b.click(); return true; }, m.actions.indexOf(a)).catch(() => false);
    await wait(900);
    const heard = (await logLines(p)).slice(before).some(l => l.who === "Screen" && /hears .*"type":"action"/.test(l.text) && l.text.includes('"' + a.key + '"'));
    step(tapped && heard ? true : false, tapped ? "the Host taps " + a.label + ": " + (heard ? "the screen heard { type: \"action\", key: \"" + a.key + "\" }" : "the screen never heard it: listen with L.on(\"action\", fn)") : "no " + a.label + " tile on the Host's phone");
  }
  let guest = null;
  area = "Player's remote";
  if (m.guests) {
    guest = await sealed(p, "g1", "guest", 10000);
    step(!!guest, guest ? (guestsN > 1 ? guestsN + " Players join" : "a Player joins") + " (view guest) and the screen hears of them" : "a Player's phone page did not say hello (view guest)");
    await wait(800);
    await phoneShot("g1", "4-guest-phone", "a Player's phone");
    // the Player's remote at its real size, 390 x 844: it fills the phone and never scrolls
    if (guest) {
      const fit = await guest.evaluate(() => { const d = document.scrollingElement || document.documentElement; return { sh: d.scrollHeight, ch: innerHeight, sw: d.scrollWidth, cw: innerWidth, fill: [...document.body.children].some(e => { const r = e.getBoundingClientRect(); return r.height >= innerHeight * 0.9; }) }; }).catch(() => null);
      if (fit) step(fit.sh <= fit.ch + 1 && fit.sw <= fit.cw + 1, fit.sh <= fit.ch + 1 && fit.sw <= fit.cw + 1 ? "the Player's remote fits the phone (390 x 844) without scrolling" + (fit.fill ? "" : ", though nothing fills its height: a remote is the whole phone") : "the Player's remote scrolls (" + fit.sh + " px tall in a phone of " + fit.ch + "): it must fit the whole phone, one screen, no scrolling");
      await showRig("g1");
      const real = await p.evaluate(() => { const g = document.querySelector('figure.sim-phone[data-rig="g1"] .sim-glass'), f = g && g.querySelector("iframe"); if (!g || !f) return false; SIM.still = true; g.dataset.was = g.style.cssText + "|" + f.style.transform; g.style.width = "390px"; g.style.height = "844px"; g.style.margin = "0"; g.style.borderRadius = "0"; f.style.transform = "none"; return true; });
      if (real) { await wait(300); const el = await p.$('figure.sim-phone[data-rig="g1"] .sim-glass iframe'); if (el) await shot("4-player-remote-390x844", "the Player's remote at 390 x 844, as on a phone", el);
        await p.evaluate(() => { const g = document.querySelector('figure.sim-phone[data-rig="g1"] .sim-glass'); g.style.margin = ""; g.style.borderRadius = ""; SIM.still = false; dispatchEvent(new Event("resize")); }); await wait(300); }
    }
  }
  await shot("5-room", "the whole room: the screen, the Host's phone and the Players, with the log");

  // 4. a Player taps the main button: the biggest button that is on screen and enabled
  if (guest) {
    const before = (await logLines(p)).length;
    const tapped = await guest.evaluate(() => {
      const b = [...document.querySelectorAll("button, [role=button]")].filter(x => !x.disabled && x.offsetWidth > 0 && x.offsetHeight > 0)
        .map(x => ({ x, a: x.getBoundingClientRect().width * x.getBoundingClientRect().height })).sort((a, b) => b.a - a.a)[0];
      if (!b) return null; const r = b.x.getBoundingClientRect(); b.x.click();
      return { label: (b.x.getAttribute("aria-label") || b.x.textContent || "").trim().slice(0, 40), w: Math.round(r.width), h: Math.round(r.height), cy: Math.round(r.top + r.height / 2), vh: innerHeight };
    }).catch(() => null);
    await wait(1500);
    const after = (await logLines(p)).slice(before);
    if (!tapped) step(null, "the Player's page has no button to tap");
    else {
      const sent = after.filter(l => /Lamba\.send/.test(l.text)).length, heard = after.filter(l => /^app: hears|hears /.test(l.text)).length;
      step(sent > 0 ? true : null, "a Player taps their biggest button (\"" + tapped.label + "\", " + tapped.w + " x " + tapped.h + " px): " + (sent ? sent + " message(s) sent, " + heard + " heard" : "no message was sent"));
      if (tapped.w < 44 || tapped.h < 44) step(false, "the Player's main button is smaller than 44 px: make it big, low in the middle, where the thumb rests");
      else if (tapped.cy < tapped.vh * 0.4) step(null, "the Player's main button sits in the top part of the phone: the thumb rests low in the middle (design rules)");
      await phoneShot("g1", "4-guest-after-tap", "the Player's phone after the tap");
      await tvShot("1-tv-after-guest-tap", "the screen after the Player's tap");
    }
  }

  // the remote's OK button, for an app that asks for it
  if (m.remote && m.remote.ok) {
    const before = (await logLines(p)).length;
    await p.dispatchEvent("#okBtn", "pointerdown"); await wait(250); await p.dispatchEvent("#okBtn", "pointerup"); await wait(1200);
    const keyed = (await logLines(p)).slice(before).some(l => /key/.test(l.text));
    step(keyed ? true : null, "the remote's OK button: " + (keyed ? "the screen page heard it (Lamba.onKey)" : "pressed; nothing in the log said the app heard it"));
    await tvShot("1-tv-after-remote-ok", "the screen after the remote's OK button");
  }

  // the phone's motion and camera, for an app that declares them: the simulator makes both up (the Phone sensors panel)
  const perms = Array.isArray(m.permissions) ? m.permissions : [], sensorPhone = guest || owner;
  if (perms.includes("motion") || perms.includes("camera")) {
    if (!sensorPhone) step(null, "the app declares motion or camera, but no phone page ran to try them on");
    else {
      if (perms.includes("motion")) {
        const r = await sensorPhone.evaluate(async () => {
          const got = window.__lt = { tilt: 0, swing: 0, shake: 0, last: null, power: null };
          Lamba.motion.on("tilt", t => { got.tilt++; got.last = t; }); Lamba.motion.on("swing", s => { got.swing++; got.power = s.power; }); Lamba.motion.on("shake", () => { got.shake++; });
          return Promise.race([Lamba.motion.start(), new Promise(ok => setTimeout(() => ok("late"), 4000))]);
        }).catch(e => "error: " + e.message);
        await p.evaluate(() => { SIM_SENSORS.tilt(0.6, -0.4); SIM_SENSORS.swing(); SIM_SENSORS.shake(); });
        await wait(600);
        const got = await sensorPhone.evaluate(() => window.__lt).catch(() => null);
        const good = r === "on" && got && got.tilt > 0 && got.swing > 0 && got.shake > 0 && got.last && typeof got.last.x === "number";
        step(good ? true : false, good ? "motion: Lamba.motion.start() is \"on\" and the page hears tilt, a swing and a shake (made up in the simulator's Phone sensors panel)" : "motion: Lamba.motion did not deliver (start gave " + JSON.stringify(r) + ", heard " + JSON.stringify(got) + "): is \"motion\" in permissions, and is this a phone page?");
        await sensorPhone.evaluate(() => Lamba.motion.stop()).catch(() => {});
      }
      if (perms.includes("camera")) {
        const r = await sensorPhone.evaluate(async () => {
          const s = window.__lcs = Lamba.track.start({ camera: "front", pose: true, hands: true, face: false, rate: 20 }), got = window.__lc = { frames: 0, hands: 0, pose: 0, v: 0 };
          s.on("frame", f => { got.frames++; got.v = f.v; if (f.hands && f.hands.length) got.hands++; if (f.pose && f.pose.length === 33) got.pose++; });
          return Promise.race([s.ready.then(() => "running", e => "error: " + e.message), new Promise(ok => setTimeout(() => ok("late"), 6000))]);
        }).catch(e => "error: " + e.message);
        await wait(1500);
        const got = await sensorPhone.evaluate(() => { const g = window.__lc; if (window.__lcs) window.__lcs.stop(); return g; }).catch(() => null);
        const good = r === "running" && got && got.frames > 5 && got.v === 1 && got.hands > 0 && got.pose > 0;
        step(good ? true : false, good ? "camera: Lamba.track.start() runs and the page gets " + got.frames + " frames of body and hand landmarks (a made-up person in the simulator's Phone sensors panel; the real camera picture never reaches your page)" : "camera: Lamba.track did not deliver frames (" + JSON.stringify(r) + ", " + JSON.stringify(got) + "): is \"camera\" in permissions, and is this a phone page?");
      }
    }
  }

  // 5. the old screen size
  area = "Screen";
  await p.click('#moreBtn'); await p.click('#optBtn'); await p.click('[data-tv="old"]'); await p.keyboard.press('Escape'); await wait(2200);
  const oldTv = await sealed(p, "tv", "screen", 8000);
  step(!!oldTv, oldTv ? "the screen page runs at the old screen size, 960 x 540" : "the screen page did not start at the old screen size");
  await tvShot("2-tv-960x540", "the screen at the old screen size, 960 x 540");
  await p.click('#moreBtn'); await p.click('#optBtn'); await p.click('[data-tv="hd"]'); await p.keyboard.press('Escape'); await wait(1500);

  // 6. every settings group of lamba.json, choice by choice, sent to the screen
  area = "Host's phone";
  const groups = ((m.settings || {}).groups || []).filter(g => g && g.key && Array.isArray(g.parts));
  for (const g of QUICK ? groups.slice(0, 1) : groups) {
    for (const part of g.parts.slice(0, QUICK ? 1 : 6)) {
      const pk = part.setting || part.app; if (!pk) continue;
      await harvest();
      // with the Players still in the room, so the screen shows the app in use (not the full join card) as each choice lands
      await p.goto(base + "/devs/simulator/?app=local" + (guestsN ? "&guests=" + guestsN : "") + "&g=" + encodeURIComponent(g.key) + "&p=" + encodeURIComponent(pk));
      seen = 0;
      const host = await until(async () => rigFrame(p, "owner"), 10000);
      await sealed(p, "tv", "screen", 10000); await wait(1200);
      const before = (await logLines(p)).length;
      const label = g.label + (g.parts.length > 1 ? ", " + part.label : "");
      if (!host) { step(false, "settings " + label + ": the Host's phone did not open"); continue; }
      if (part.app) {
        const pf = await sealed(p, "owner", "part", 8000);
        step(!!pf, "settings " + label + ": the app draws this part itself (view part)" + (pf ? "" : ", but it never said hello"));
        await phoneShot("owner", "6-settings-" + slug(g.key) + "-" + slug(pk), "settings: " + label + " on the Host's phone");
        R.settings.push({ group: g.key, part: pk, choices: [], app: true, ok: !!pf });
        continue;
      }
      const field = ((m.settings || {}).fields || {})[pk] || {};
      const n2 = await host.evaluate(() => document.querySelectorAll(".ctl-strip button").length).catch(() => 0);
      const tried = [];
      const count = Math.min(n2, QUICK ? 2 : 8);
      for (let i = 0; i < count; i++) {
        const name = await host.evaluate(i => { const b = document.querySelectorAll(".ctl-strip button")[i]; if (!b) return null; b.click(); return b.getAttribute("aria-label") || b.textContent.trim(); }, i).catch(() => null);
        if (name === null) break;
        await wait(350);
        await host.evaluate(() => { const s = [...document.querySelectorAll("button")].find(b => /^Send to /i.test(b.textContent) && b.offsetWidth > 0 && !b.disabled); if (s) s.click(); }).catch(() => {});
        await host.evaluate(() => { const s = document.getElementById("simSend"); if (s && s.offsetWidth > 0) s.click(); }).catch(() => {});   // the simulator's Send to screen (the Host's changes wait for it, as on Lamba)
        await wait(900);
        tried.push(name);
        if (i === 0 || i === count - 1) await tvShot("6-settings-" + slug(g.key) + "-" + slug(pk) + "-" + slug(name), "settings: " + label + ", " + name + ", on the screen");
      }
      if (!n2) await phoneShot("owner", "6-settings-" + slug(g.key) + "-" + slug(pk), "settings: " + label + " on the Host's phone (" + (field.type || "?") + ")");
      const sent = (await logLines(p)).slice(before).filter(l => l.kind === "settings" && /sent to the screen/.test(l.text)).length;
      R.settings.push({ group: g.key, part: pk, type: field.type || "", choices: tried, sent });
      step(n2 ? sent > 0 : null, "settings " + label + ": " + (n2 ? tried.length + " choice(s) tried (" + tried.join(", ") + "), " + sent + " sent to the screen" : "a " + (field.type || "control") + " (screenshot only: the test taps pictures, not dials or fields)"));
    }
  }

  // 7. what the log says: problems, refusals, every SDK message
  await harvest();
  R.errors = [...new Set(R.errors)]; R.problems = [...new Set(R.problems)]; R.refused = [...new Set(R.refused)];
  await ctx.close();
  return R;
}

// the short 3-column summary: what was tested, the result, what to fix (one row for the screen, the Host's phone, the Player's remote)
const AREAS = ["Check", "Screen", "Host's phone", "Player's remote"];
function table(R) {
  const cell = t => String(t).replace(/\|/g, "/").replace(/\s+/g, " ");
  const rows = [];
  for (const a of AREAS) {
    const st = R.steps.filter(s => s.area === a);
    if (!st.length) { if (a === "Player's remote") rows.push([a + ": no Players in this app", "not tested", "nothing"]); continue; }
    const bad = st.filter(s => s.ok === false), what = st.length + " check" + (st.length > 1 ? "s" : "") + (a === "Host's phone" && R.settings.length ? ", " + R.settings.length + " settings part" + (R.settings.length > 1 ? "s" : "") : "");
    const nudge = st.filter(s => s.ok === null && /^the phone page builds its own controls/.test(s.text));   // phone design warnings: flagged in the table
    rows.push([cell(a + ": " + what), bad.length ? bad.length + " to fix" : st.some(s => s.ok === null) ? "ok, with a note" : "ok", cell(bad.length ? bad.map(s => s.text).join("; ").slice(0, 240) : nudge.length ? nudge.map(s => s.text).join("; ").slice(0, 240) : "nothing")]);
  }
  const loose = R.errors.length + R.problems.length + R.refused.length;
  rows.push(["Errors, refused messages, content rules", loose ? loose + " to fix" : "ok", cell(loose ? R.errors.concat(R.problems, R.refused).slice(0, 2).join("; ").slice(0, 240) : "nothing")]);
  return rows;
}
function summary(all) {
  const L = ["# lamba test", "", "Ran " + new Date().toISOString().replace("T", " ").slice(0, 19) + " UTC. Screenshots are in this folder: open them and look before you change anything.", ""];
  let good = true;
  for (const R of all) {
    const fixes = (R.check && !R.check.ready ? R.check.problems.length : 0) + R.errors.length + R.problems.length + R.refused.length + R.steps.filter(s => s.ok === false).length;
    if (fixes) good = false;
    L.push("## " + R.name + " (" + R.app + "): " + (fixes ? fixes + " to fix" : "nothing to fix"), "");
    L.push("### Summary", "", "| What was tested | Result | What to fix |", "| --- | --- | --- |");
    table(R).forEach(r => L.push("| " + r.join(" | ") + " |")); L.push("");
    L.push("### Steps", ""); R.steps.forEach(s => L.push("- " + (s.ok === true ? "ok: " : s.ok === false ? "FIX: " : "note: ") + s.text)); L.push("");
    if (R.check) {
      L.push("### The check (" + R.check.badge + ")", "");
      (R.check.ready ? R.check.notes : R.check.problems).forEach(t => L.push("- " + t)); L.push("");
    }
    if (R.errors.length) { L.push("### Errors in a page", ""); R.errors.forEach(t => L.push("- " + t)); L.push(""); }
    if (R.problems.length) { L.push("### Problems the simulator logged", ""); R.problems.forEach(t => L.push("- " + t)); L.push(""); }
    if (R.refused.length) { L.push("### Refused by the room or the host", ""); R.refused.forEach(t => L.push("- " + t)); L.push(""); }
    if (R.notes.length) { L.push("### Notes", ""); R.notes.forEach(t => L.push("- " + t)); L.push(""); }
    L.push("### Screenshots", ""); R.shots.forEach(s => L.push("- " + s.file + ": " + s.what)); L.push("");
    L.push("### SDK messages (" + R.messages.length + ", the first 60)", ""); R.messages.slice(0, 60).forEach(t => L.push("- " + t)); L.push("");
  }
  if (missing.size) { L.push("### Inside the test", "", "- the simulator asked for files this copy of lamba-test.mjs does not have: " + [...missing].join(", ") + ". Get the newest at https://lamba.tv/devs/kit/lamba-test.mjs", ""); }
  L.push(good ? "Result: nothing to fix. Next: replace placeholder clips if you still have them, then upload." : "Result: fix what is marked FIX and what is listed above, then run node lamba-check.mjs and node lamba-test.mjs again.");
  return { text: L.join("\n") + "\n", good };
}

// ---------- the command ----------
let dirs = named.map(a => resolve(a));
if (!dirs.length) {
  const here = process.cwd();
  dirs = existsSync(join(here, "lamba.json")) ? [here] : readdirSync(here).filter(n => !SKIP(n) && existsSync(join(here, n, "lamba.json"))).map(n => join(here, n));
  if (!dirs.length) { say("lamba test: no app here. Run it with your app's folder: node lamba-test.mjs my-app"); process.exit(2); }
}
for (const d of dirs) if (!existsSync(join(d, "lamba.json"))) { say("lamba test: " + d + " has no lamba.json (choose your app's own folder)"); process.exit(2); }
if (SERVE) {
  const dir = dirs[0], m = (() => { try { return JSON.parse(readFileSync(join(dir, "lamba.json"), "utf8")); } catch (e) { return null; } })();
  if (!m) { say("lamba test: " + join(dir, "lamba.json") + " is not readable JSON. Fix it, then run this again."); process.exit(2); }
  const slug = (basename(dir).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").replace(/^[^a-z]+/, "") || "my-app").slice(0, 40).replace(/-+$/, "") || "my-app";
  const pl = m.players || {}, guestsN = m.guests ? Math.max(1, Math.min(2, pl.min || 1, pl.max || 1)) : 0;
  const host = opt("--host") || "127.0.0.1", want = opt("--port") === null ? 8787 : parseInt(opt("--port"), 10);
  if (!(want >= 0 && want < 65536)) { say("lamba test: --port needs a number, like --port 8787"); process.exit(2); }
  let srv;
  try { srv = await serve(want, host, { dir, slug }); } catch (e) { say("lamba test: could not start the server: " + e.message); process.exit(2); }
  const port = srv.address().port, shown = host === "0.0.0.0" || host === "::" ? "127.0.0.1" : host;
  say("Play " + (m.name || basename(dir)) + " at http://" + shown + ":" + port + "/devs/simulator/?example=" + slug + (guestsN ? "&guests=" + guestsN : "") + " (reload the page after an edit, Ctrl+C to stop)");
  if (dirs.length > 1) say("(only " + basename(dir) + " is served; name one app to choose)");
  if (shown !== host) { const nets = Object.values(os.networkInterfaces()).flat().filter(n => n && n.family === "IPv4" && !n.internal); for (const n of nets) say("On a phone on the same Wi-Fi: http://" + n.address + ":" + port + "/devs/simulator/?example=" + slug + (guestsN ? "&guests=" + guestsN : "")); }
  const bye = () => { srv.close(); process.exit(0); };
  process.on("SIGINT", bye); process.on("SIGTERM", bye);
  await new Promise(() => {});
}
rmSync(SHOTS, { recursive: true, force: true }); mkdirSync(SHOTS, { recursive: true });
const server = await serve(0, "127.0.0.1"), base = "http://127.0.0.1:" + server.address().port;
let browser;
try { browser = await chromium.launch({ headless: !HEADED, args: ["--mute-audio"] }); }
catch (e) { say("lamba test: Chromium is not installed for Playwright. Run: npx playwright install chromium\n  (" + e.message.split("\n")[0] + ")"); server.close(); process.exit(2); }
const all = [];
try {
  for (const d of dirs) { say("lamba test: " + basename(d)); all.push(await testApp(d, base, browser, dirs.length)); }
} catch (e) { say("lamba test: the test stopped: " + (e && e.message ? e.message.split("\n")[0] : e)); await browser.close(); server.close(); process.exit(2); }
await browser.close(); server.close();
const s = summary(all);
writeFileSync(join(SHOTS, "summary.md"), s.text);
writeFileSync(join(SHOTS, "summary.json"), JSON.stringify({ good: s.good, table: all.map(R => ({ app: R.app, rows: table(R) })), apps: all, missing: [...missing] }, null, 1) + "\n");
say("\nWhat was tested | Result | What to fix\n" + all.map(R => table(R).map(r => "  " + r[0].padEnd(40) + r[1].padEnd(18) + r[2]).join("\n")).join("\n") + "\n");
say(s.text + "\nWritten: " + relative(process.cwd(), join(SHOTS, "summary.md")) + " and " + all.reduce((n, R) => n + R.shots.length, 0) + " screenshots in " + (relative(process.cwd(), SHOTS) || "."));
if (process.env.LAMBA_TEST_ASKED) writeFileSync(process.env.LAMBA_TEST_ASKED, [...asked].sort().join("\n") + "\n");
process.exit(s.good ? 0 : 1);
